#!/usr/bin/env python3
from ta_emss import ta_emss
import time

if __name__ == "__main__":

    ################################################################################
    # Create EMSS instance and setup BTS OAM for 128 X2AP links (default is 64)
    ################################################################################
    emss1 = ta_emss()
    emss1.setup_emss(bts_id=1)
    mrbts_id = emss1.get_object_id('MRBTS')
    emss1.configure_bts([{'MOC': 'ANR', 'ID': 0, 'maxNumX2LinksIn': 128}])

    ################################################################################
    # Configure Xterminator with 128 eNBs and IP addresses
    ################################################################################
    print("Setting xterminator up...")
    emss1.xterm_setup(
        # BTS section
        bts_ip_addr="10.0.1.2",
        # ENBsim local IP section
        enbsim_ip_addr_begin="10.0.201.1",
        enbsim_ip_addr_end="10.0.201.128",
        enbsim_ip_addr_mask=24,
        enbsim_eth_if="eth3",
        # MME IP for S1 IPSEC tunnel
        mme_ip_addr="10.0.1.1",
        mme_ip_addr_mask=24,
        # IPSEC section
        bts_oam_ip_addr="192.168.255.129",
        ipsec_x2=True,
        ipsec_s1=True,
        ipsec_policy_order_num_begin=2,
        # ENBsim configuration
        init_enb_pci_max=503,
        init_enb_enb_id=4001,
        init_enb_mcc="244",
        init_enb_mnc="08",
        init_enb_tac=1,
        init_enb_dl_earfcn=4900,
        init_enb_dl_bandwidth=10,
        # X2AP setup configuration
        x2ap_setup_period=15,
        x2ap_setup_retries=3,
        x2ap_reset_period=15,
        x2ap_reset_retries=3,
        # X2AP scenario configuration
        enb_configuration_update_min=60,
        enb_configuration_update_max=300,
        x2_reset_min=300,
        x2_reset_max=360,
        # General params
        verbose=True,
        debug=False
    )

    ################################################################################
    # Start X2AP simulation connecting 128 X2 links to BTS
    ################################################################################
    print("Starting X2AP simulation...")
    emss1.xterm_start(x2ap=True)

    k = ""
    while True:
        k = input("Enter 'x' to start IPSEC...")
        if k == "x":
            break

    print("CONFIGURE IPSEC")

    # --- ADD IPSEC CONFIG ---
    bts_ip_addr = emss1.xterm_get('BTS_IP_ADDR')
    policy_order_number = emss1.xterm_get('IPSEC_POLICY_ORDER_NUM_BEGIN')

    configure_ipsec_mocs_command = []

    configure_ipsec_mocs_command.append({'MOC': 'IPAPP', 'ID': '1-1-1'})
    configure_ipsec_mocs_command.append({'MOC': 'IPSECC', 'ID': '1-1-1-1',
                                         'authenticationScheme': 'PSK',
                                         'ipSecEnabled': 'true',
                                         'x2TunnelAutoRemovalEnabled': 'true'})
    configure_ipsec_mocs_command.append({'MOC': 'IPSECP', 'ID': '1-1-1-1-1',
                                         'antiReplayWindowSize': 'SIZE_128'
                                         })

    moc_id = 1
    for enb in emss1.xterm_get("enbs"):
        configure_ipsec_mocs_command.append({'MOC': 'IKEP', 'ID': f'1-1-1-1-{moc_id}',
                                             'localTunnelEndpointDN': f'MRBTS-{mrbts_id}/TNLSVC-1/TNL-1/IPNO-1/IPIF-1/IPADDRESSV4-1',
                                             'remoteTunnelEndpoint': enb['IP_ADDR']
                                             })
        configure_ipsec_mocs_command.append({'MOC': 'SECPOL', 'ID': f'1-1-1-1-{moc_id}',
                                             'ikePDN': f'MRBTS-{mrbts_id}/TNLSVC-1/TNL-1/IPAPP-1/IPSECC-1/IKEP-{moc_id}',
                                             'ipSecPDN': f'MRBTS-{mrbts_id}/TNLSVC-1/TNL-1/IPAPP-1/IPSECC-1/IPSECP-1',
                                             'policyOrderNumber': policy_order_number,
                                             'trafficSelectorList': [{'localIpAddress': bts_ip_addr,
                                                                      'dynamicLocalIpAddressDN': '',
                                                                      'policyAnchor': '',
                                                                      'localIpPrefixLength': '32',
                                                                      'remoteIpAddress': enb['IP_ADDR'],
                                                                      'remoteIpPrefixLength': '32'
                                                                      }]
                                             })
        policy_order_number += 1
        moc_id += 1

    if emss1.xterm_get('IPSEC_S1'):
        mme_ip_addr = emss1.xterm_get('MME')['MME_IP_ADDR']
        configure_ipsec_mocs_command.append({'MOC': 'IKEP', 'ID': f'1-1-1-1-{moc_id}',
                                             'localTunnelEndpointDN': f'MRBTS-{mrbts_id}/TNLSVC-1/TNL-1/IPNO-1/IPIF-1/IPADDRESSV4-1',
                                             'remoteTunnelEndpoint': mme_ip_addr,
                                             })
        configure_ipsec_mocs_command.append({'MOC': 'SECPOL', 'ID': f'1-1-1-1-{moc_id}',
                                             'ikePDN': f'MRBTS-{mrbts_id}/TNLSVC-1/TNL-1/IPAPP-1/IPSECC-1/IKEP-{moc_id}',
                                             'ipSecPDN': f'MRBTS-{mrbts_id}/TNLSVC-1/TNL-1/IPAPP-1/IPSECC-1/IPSECP-1',
                                             'policyOrderNumber': policy_order_number,
                                             'trafficSelectorList': [{'localIpAddress': bts_ip_addr,
                                                                      'dynamicLocalIpAddressDN': '',
                                                                      'policyAnchor': '',
                                                                      'localIpPrefixLength': '32',
                                                                      'remoteIpAddress': mme_ip_addr,
                                                                      'remoteIpPrefixLength': '32'
                                                                      }]
                                             })
        policy_order_number += 1
        moc_id += 1

    emss1.configure(configure_ipsec_mocs_command, skip_np=False)
    time.sleep(5)

    ################################################################################
    # Press the key to stop X2 simulation and delete dynamically created LNADJs
    ################################################################################
    k = ""
    while True:
        k = input("Enter 'q' to stop simulation...")
        if k == "q":
            break

    print("Stopping xterm")
    emss1.xterm_teardown()

    print("Deleting LNADJs")
    emss1.configure_delete("LNADJ")

    # --- DELETE IPSEC MOCS ---
    print("DELETE IPSEC MOCS")
    delete_moc_command = []
    delete_moc_command.append({'DEL': 'IPAPP', 'ID': '1-1-1'})

    emss1.configure_bts(delete_moc_command)
